	ldcf_dd16 7, 0x06, 0x04
	scc8 c, a
	cps a, 1
	scc16 z, hl
	ret

LABEL_EF07A2:
	cps a, 2
	jr nz, LABEL_EF07C8
	call 0xFFFEE5
	and l, 0xF
	extz hl
	ldada_24 xbc, 0xe00000
	ld_srib3 C, 0x07, 0xE4, 0xEC
	extz bc
