	dec 8, xsp
	push xiz
	ld xwa, 0xFFFFFFFF
	ld (xsp + 8), xwa
	ei 6
	ld xwa, 0xAA00AA
	stda32_24 0x815554, xwa
	ld xwa, 0x550055
	stda32_24 0x80aaa8, xwa
	ld xwa, 0x900090
	stda32_24 0x815554, xwa
	ldda32_24 xwa, 0x800000
	ld (xsp + 4), xwa
	ld xwa, 0x800000
	ld xiz, (xwa + 4)
	ei 0
	ld xwa, (xsp + 4)
	cp xwa, 0x10001
	jr z, LABEL_EF3D5E
	cp xwa, 0x40004
	jr nz, LABEL_EF3D74

